package ui;

import core.payload.response.PostResponse;
import javafx.fxml.FXML;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;
import service.PostService;
import service.UserService;

// This JavaDoc comment was generated by Github Copilot
/**
 * Controller for individual post UI component. Binds Post data to the post.fxml
 * labels.
 */
@Component
@Scope("prototype") // Tells springboot to create individual PostController class for posts
public class PostController {
  private final PostService postService;
  private final UserService userService;

  /** Controller injects the necessary services. */
  @Autowired
  public PostController(PostService postService, UserService userService) {
    this.postService = postService;
    this.userService = userService;
  }

  @FXML
  private Label displayNameLabel;
  @FXML
  private Label usernameLabel;
  @FXML
  private Label contentLabel;
  @FXML
  private Button likeBtn;
  @FXML
  private Button retweetBtn;

  private PostResponse currentPost;

  // This JavaDoc comment was generated by Github Copilot
  /** Sets the Post data to the UI labels. */
  @FXML
  public void setData(PostResponse post) {
    this.currentPost = post;

    displayNameLabel.setText(post.author().displayName());
    usernameLabel.setText("@" + post.author().username());
    contentLabel.setText(post.content());
    likeBtn.setText(post.likes() + " 👍");
    retweetBtn.setText(post.reTweets() + " 🔄");

    if (post.likedByUser(userService.getLoggedInUser().id())) {
      likeBtn.setStyle("-fx-text-fill: blue;");
    }
    // updateLikes();
    // if (post.reTweetedByUser(userService.getLoggedInUser()))
    // retweetBtn.setStyle("-fx-text-fill: cyan;");
  }

  /** Updates the likes UI elements when the like button is pressed. */
  @FXML
  public void updateLikes() {
    if (currentPost != null) {
      currentPost = postService.likePost(currentPost.id());
      likeBtn.setText(currentPost.likes() + " 👍");

      if (currentPost.likedByUser(userService.getLoggedInUser().id())) {
        likeBtn.setStyle("-fx-text-fill: blue;");
      } else {
        likeBtn.setStyle("-fx-text-fill: black;");
      }
    }
  }

  /** Updates the retweet UI elements when the retweet button is pressed. */
  @FXML
  public void updateRetweets() { // do not remove, posts wont show
  }
}
